<?php $events = (array) ($project['academic_history'] ?? []); ?>
<section class="sw-card"><header class="sw-section-heading"><div><h2>Historial académico</h2><p>Eventos académicos registrados para este proyecto.</p></div></header><?php if (!$events): ?><p class="sw-empty-state">No hay historial adicional registrado.</p><?php else: ?><div class="sw-history-list"><?php foreach ($events as $event): ?><article class="sw-history-event"><div><strong><?= e((string)($event['title'] ?? 'Evento académico')) ?></strong><?php if (!empty($event['description'])): ?><p><?= e((string)$event['description']) ?></p><?php endif; ?></div><small><?= e($formatDate((string)($event['occurred_at_local'] ?? $event['date'] ?? ''), true)) ?><?= !empty($event['actor']) ? ' · ' . e((string)$event['actor']) : '' ?></small></article><?php endforeach; ?></div><?php endif; ?></section>
